-- Review-gated environmental clearance and EPR compliance routes.

do $$
declare
  item jsonb;
  authority_id uuid;
  seed_opportunity_id uuid;
  version_id uuid;
begin
  for item in
    select value from jsonb_array_elements($records$[
      {"slug":"cpcb-plastic-packaging-epr-registration","name":"CPCB Plastic Packaging Extended Producer Responsibility Registration","type":"environmental_compliance","status":"active","authority":"Central Pollution Control Board - Plastic Packaging EPR","authority_url":"https://cpcb.nic.in/","canonical_url":"https://cpcb.nic.in/rules-7/","source_url":"https://cpcb.nic.in/uploads/plasticwaste/SOP_PWM_24062024.pdf","source_kind":"guideline","source_title":"CPCB plastic EPR SOP","source_anchor":"Plastic packaging EPR coverage, mandatory registration categories, portal route, targets and consequences","summary":"Mandatory CPCB-linked registration and continuing EPR obligations for covered plastic-packaging producers, importers, brand owners and plastic-waste processors.","objective":"Track registration, recycling, reuse, recycled-content and end-of-life obligations for covered plastic packaging.","legal_basis":"Plastic Waste Management Rules and CPCB plastic-packaging EPR guidance; current categories, portal fields and State Pollution Control Board route control the case.","eligibility":{"entity_types":["plastic_packaging_producer","plastic_packaging_importer","brand_owner","plastic_waste_processor"],"lifecycle_stages":["starting","operating","expanding"],"industries":["consumer_goods","food_processing","retail","packaging","manufacturing","waste_processing"],"locations":["India","state_or_ut"],"conditions":["entity must fall within a covered plastic-packaging or processor category","registration is required before carrying on covered business","multiple categories and State units require separate treatment under the SOP","targets, returns, certificates and records remain after registration"],"thresholds":{"registration_required":true,"multiple_categories_separate_registration":true,"multiple_state_units_separate_treatment":true},"unknown_handling":"needs_information"},"application":{"portal":"https://cpcbeprplastic.in/","route":"Classify the entity and packaging, assemble PAN/GST/CIN/authorized-person and unit information, register in each applicable category/state and maintain EPR records.","selection":"CPCB, SPCB/PCC and the centralized portal process registration; UdyamVeda cannot issue it.","fees":"Current portal fees must be confirmed; no universal fee is asserted here.","applicant_note":"UdyamVeda may prepare the checklist but must not impersonate a producer, brand owner, processor or regulator."},"fine_print":{"covered_entities":"The SOP covers Producer, Importer, Brand Owner and Plastic Waste Processor categories.","obligations":"Registration is only the entry point; reuse, recycling, recycled content, end-of-life, targets, records and certificates remain separate obligations.","review_note":"Verify current rule amendments, category, State route, portal fields, documents, fees, targets, returns, certificates and enforcement before publication."},"benefit_summary":{"types":["regulatory_approval","compliance"],"summary":"Plastic-packaging compliance registration and obligation tracking; not a financial benefit.","separate_value_buckets":true},"benefit_type":"compliance_registration","benefit_label":"CPCB plastic packaging EPR registration and compliance route","amount_min":null,"amount_max":null,"percentage":null,"benefit_conditions":{"registration_required":true,"epr_obligations_continue_after_registration":true,"separate_category_and_state_treatment":true},"requirement":"Entity identity, packaging/category details, State/unit information and EPR declarations","requirement_description":"Prepare PAN, GST, CIN where applicable, authorized-person identity, packaging/category data, volumes, unit States, processor information and current portal declarations.","rules":{"all":[{"field":"covered_plastic_packaging_role_verified","operator":"equals","value":true},{"field":"applicable_state_or_ut_identified","operator":"equals","value":true},{"field":"cpcb_epr_portal_route_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Classify the entity and packaging","description":"Determine the covered role and each applicable category/state.","url":"https://cpcb.nic.in/uploads/plasticwaste/SOP_PWM_24062024.pdf"},{"title":"Prepare identity and unit evidence","description":"Collect identity, packaging, authorized-person and State/unit records.","url":"https://cpcb.nic.in/rules-7/"},{"title":"Register on the CPCB-linked portal","description":"Submit the relevant registration and retain acknowledgements.","url":"https://cpcbeprplastic.in/"},{"title":"Maintain targets and records","description":"Track targets, certificates, returns, recycling and end-of-life obligations.","url":"https://cpcb.nic.in/uploads/plasticwaste/SOP_PWM_24062024.pdf"}],"window_type":"rolling","window_close_at":null,"window_label":"Standing registration and continuing-compliance route; reporting cycles and amendments require confirmation.","window_evidence":{"source_url":"https://cpcb.nic.in/uploads/plasticwaste/SOP_PWM_24062024.pdf","anchor":"SOP states covered entities shall register on the centralized portal and shall not carry on covered business without registration."},"review_note":"Keep review-gated. This is a compliance obligation, not a grant or savings estimate."},
      {"slug":"cpcb-e-waste-epr-producer-registration","name":"CPCB E-Waste Extended Producer Responsibility Registration","type":"environmental_compliance","status":"active","authority":"Central Pollution Control Board - E-Waste EPR","authority_url":"https://cpcb.nic.in/","canonical_url":"https://cpcb.nic.in/rules-7/","source_url":"https://cpcb.nic.in/uploads/Projects/E-Waste/FAQ_ewaste_23012024.pdf","source_kind":"faq","source_title":"CPCB e-waste EPR FAQ","source_anchor":"Producer registration requirement, covered entity categories, exclusions and phase-wise recycling targets","summary":"CPCB registration and recycling-obligation route for covered manufacturers, producers, recyclers and refurbishers of electrical and electronic equipment.","objective":"Ensure covered producers meet EPR recycling obligations through registered e-waste recyclers.","legal_basis":"E-Waste (Management) Rules, 2022 and CPCB official EPR FAQ; current Schedule-I coverage, portal procedure and target amendments control.","eligibility":{"entity_types":["electrical_equipment_manufacturer","electrical_equipment_producer","e_waste_recycler","e_waste_refurbisher"],"lifecycle_stages":["starting","operating","expanding"],"industries":["electronics","electrical_equipment","information_technology","consumer_durables","recycling","refurbishment"],"locations":["India"],"conditions":["role must be covered by current rules and schedules","covered producers must register","producer EPR is fulfilled through registered e-waste recyclers","targets are phase-wise and may change by amendment"],"thresholds":{"fy_2023_24_and_2024_25_target_percent":60,"fy_2025_26_and_2026_27_target_percent":70,"fy_2027_28_onwards_target_percent":80,"bulk_consumer_producer_registration":"not_required_under_faq"},"unknown_handling":"needs_information"},"application":{"portal":"https://cpcb.nic.in/rules-7/","route":"Confirm Schedule-I coverage and role, prepare product, entity and recycler records, use the current CPCB EPR portal route and retain registration evidence.","selection":"CPCB processes registration and obligations; UdyamVeda cannot issue the certificate.","fees":"Current portal fees and document limits must be confirmed.","applicant_note":"UdyamVeda may prepare a checklist but must not represent itself as CPCB, a producer or a recycler."},"fine_print":{"covered_roles":"The FAQ identifies Manufacturer, Producer, Recycler and Refurbisher as registration categories and excludes Bulk Consumer from producer registration.","targets":"The FAQ states phase-wise target references of 60%, 70% and 80%, subject to current rule confirmation.","review_note":"Verify current Schedule-I coverage, registration form, portal, targets, recycler evidence, returns, fees and enforcement before publication."},"benefit_summary":{"types":["regulatory_approval","compliance"],"summary":"CPCB e-waste EPR registration and continuing compliance; not a financial benefit.","separate_value_buckets":true},"benefit_type":"compliance_registration","benefit_label":"CPCB e-waste EPR registration and recycling-obligation route","amount_min":null,"amount_max":null,"percentage":null,"benefit_conditions":{"covered_role_registration_required":true,"registered_recycler_route_required":true,"target_schedule_changes_by_fy":true},"requirement":"Schedule-I product/role evidence, entity identity, production/sales data and recycler records","requirement_description":"Prepare entity identity, product schedule, role, quantity records, authorized-person details, registered-recycler agreements and current portal forms.","rules":{"all":[{"field":"covered_electrical_electronic_role_verified","operator":"equals","value":true},{"field":"schedule_i_product_coverage_verified","operator":"equals","value":true},{"field":"cpcb_e_waste_route_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Confirm role and Schedule-I coverage","description":"Determine the covered role and equipment schedule.","url":"https://cpcb.nic.in/uploads/Projects/E-Waste/FAQ_ewaste_23012024.pdf"},{"title":"Prepare product and quantity records","description":"Collect product, sales, entity and recycler information.","url":"https://cpcb.nic.in/rules-7/"},{"title":"Submit CPCB registration","description":"Use the current CPCB EPR portal route and retain certificate details.","url":"https://cpcb.nic.in/rules-7/"},{"title":"Track recycling targets and evidence","description":"Reconcile annual targets, recycler certificates, returns and amendments.","url":"https://cpcb.nic.in/uploads/Projects/E-Waste/FAQ_ewaste_23012024.pdf"}],"window_type":"rolling","window_close_at":null,"window_label":"Standing registration with financial-year EPR targets; dates require current CPCB confirmation.","window_evidence":{"source_url":"https://cpcb.nic.in/uploads/Projects/E-Waste/FAQ_ewaste_23012024.pdf","anchor":"FAQ states mandatory registration for covered producers and phase-wise recycling obligations."},"review_note":"Keep review-gated. Do not calculate a target without verified product quantities and current CPCB rules."},
      {"slug":"moefcc-parivesh-environmental-clearance","name":"MoEFCC Environmental Clearance through PARIVESH","type":"environmental_approval","status":"active","authority":"Ministry of Environment, Forest and Climate Change - Environmental Impact Assessment","authority_url":"https://moef.gov.in/","canonical_url":"https://parivesh.nic.in/","source_url":"https://moef.gov.in/index.php/environmental-impact-assessment-eia","source_kind":"ministry","source_title":"MoEFCC Environmental Impact Assessment","source_anchor":"EIA appraisal, two-stage projects, PARIVESH online application and complete-information decision boundary","summary":"Project-level environmental-clearance workflow through PARIVESH for activities covered by the applicable EIA regime.","objective":"Guide project proponents through screening, terms of reference, EIA/EMP, public hearing where applicable, appraisal and decision.","legal_basis":"MoEFCC EIA overview, applicable EIA notification and sector-specific environmental rules; project category and location determine approvals.","eligibility":{"entity_types":["project_proponent","company","partnership","llp","infrastructure_developer","industrial_unit","mining_operator","port_developer"],"lifecycle_stages":["starting","expanding"],"industries":["manufacturing","mining","infrastructure","ports","river_valley","chemical","petrochemical","energy","construction"],"locations":["India","project_site"],"conditions":["project/activity must fall within an applicable clearance category","site, sector, scale and sensitive-area status determine appraisal","Form-I and pre-feasibility material may be required","EIA/EMP, public hearing and appraisal stages apply where prescribed","forest, wildlife, coastal, pollution-control and local permissions may be separate"],"thresholds":{"complete_information_decision_reference_days":90,"universal_clearance_threshold":"not_applicable"},"unknown_handling":"needs_information"},"application":{"portal":"https://parivesh.nic.in/","route":"Classify the project and site, prepare prescribed forms and reports, complete hearing/appraisal stages where applicable and track the decision.","selection":"MoEFCC/EAC/SEIAA and competent authorities evaluate the proposal; UdyamVeda cannot grant clearance.","fees":"Project and authority-specific charges require confirmation.","applicant_note":"UdyamVeda may explain the workflow but must not give legal clearance advice or represent the approving authority."},"fine_print":{"workflow":"MoEFCC describes online PARIVESH submission, EIA stages, public hearing where prescribed, appraisal and competent-authority decision.","timing":"The overview states a 90-day reference for complete-information proposals; project-specific rules control.","review_note":"Verify current EIA category, site checks, PARIVESH form, TOR, EIA/EMP, hearing, forest/wildlife/CRZ/pollution-control dependencies and amendments before publication."},"benefit_summary":{"types":["regulatory_approval"],"summary":"Project-level environmental-clearance workflow; approval is conditional and not guaranteed.","separate_value_buckets":true},"benefit_type":"regulatory_approval","benefit_label":"MoEFCC environmental-clearance application and appraisal route through PARIVESH","amount_min":null,"amount_max":null,"percentage":null,"benefit_conditions":{"project_category_and_site_screening_required":true,"parivesh_route_required":true,"approval_not_guaranteed":true,"other_permissions_may_be_required":true},"requirement":"Project/site details, prescribed forms, pre-feasibility/EIA/EMP material and declarations","requirement_description":"Prepare site and project coordinates, capacity and sector details, Form-I, pre-feasibility, EIA/EMP where prescribed, hearing responses, maps and signatory information.","rules":{"all":[{"field":"project_requires_environmental_clearance","operator":"equals","value":true},{"field":"project_site_and_category_verified","operator":"equals","value":true},{"field":"parivesh_application_route_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Screen project and site","description":"Determine sector, scale, location, sensitive-area and approval dependencies.","url":"https://moef.gov.in/index.php/environmental-impact-assessment-eia"},{"title":"Create the PARIVESH proposal","description":"Prepare prescribed forms and supporting site/project material.","url":"https://parivesh.nic.in/"},{"title":"Complete EIA/public-hearing stages","description":"Where prescribed, prepare EIA/EMP and address appraisal observations.","url":"https://moef.gov.in/uploads/2024/05/iv-Citizen-Charter-MoEFCC.pdf"},{"title":"Track decision and dependencies","description":"Track the decision and complete separate permissions where applicable.","url":"https://moef.gov.in/index.php/environmental-impact-assessment-eia"}],"window_type":"rolling","window_close_at":null,"window_label":"Rolling project-approval route; project-specific submissions and authority requests determine timing.","window_evidence":{"source_url":"https://moef.gov.in/index.php/environmental-impact-assessment-eia","anchor":"MoEFCC describes online application, appraisal and a 90-day decision reference for complete-information proposals."},"review_note":"Keep review-gated. A PARIVESH submission or estimated timeline is not an environmental clearance."}
    ]$records$::jsonb)
  loop
    authority_id := null;
    insert into public.authorities (name, level, ministry, department, official_url)
    select item->>'authority', 'central', case when item->>'type' = 'environmental_approval' then 'Ministry of Environment, Forest and Climate Change' else 'Ministry of Environment, Forest and Climate Change' end, 'Environmental clearance and Central Pollution Control Board routes', item->>'authority_url'
    where not exists (select 1 from public.authorities where name = item->>'authority')
    returning id into authority_id;
    if authority_id is null then select id into authority_id from public.authorities where name = item->>'authority' limit 1; end if;
    seed_opportunity_id := null;
    insert into public.opportunities (slug, name, opportunity_type, status, authority_id, geography, canonical_url)
    values (item->>'slug', item->>'name', item->>'type', item->>'status', authority_id, '{"coverage":"central","locations":["India"]}'::jsonb, item->>'canonical_url')
    on conflict (slug) do update set name = excluded.name, status = excluded.status, authority_id = excluded.authority_id, canonical_url = excluded.canonical_url
    returning id into seed_opportunity_id;
    if seed_opportunity_id is null then select id into seed_opportunity_id from public.opportunities where slug = item->>'slug' limit 1; end if;
    version_id := null;
    insert into public.opportunity_versions
      (opportunity_id, version_number, title, summary, objective, legal_basis, eligibility, application, fine_print, benefit_summary, last_verified_at, completeness, confidence, review_status)
    values (seed_opportunity_id, 1, item->>'name', item->>'summary', item->>'objective', item->>'legal_basis', item->'eligibility', item->'application', item->'fine_print', item->'benefit_summary', now(), 0.9, 0.85, 'in_review')
    on conflict (opportunity_id, version_number) do nothing
    returning id into version_id;
    if version_id is null then select ov.id into version_id from public.opportunity_versions ov where ov.opportunity_id = seed_opportunity_id and ov.version_number = 1 limit 1; end if;
    update public.opportunities set current_version_id = version_id, status = item->>'status' where id = seed_opportunity_id;
    insert into public.opportunity_sources (opportunity_version_id, source_url, source_kind, source_title, source_anchor, fetched_at, is_primary)
    values
      (version_id, item->>'source_url', item->>'source_kind', item->>'source_title', item->>'source_anchor', now(), true),
      (version_id, 'https://moef.gov.in/index.php/environmental-impact-assessment-eia', 'ministry', 'MoEFCC Environmental Impact Assessment', 'EIA and appraisal workflow', now(), false),
      (version_id, 'https://moef.gov.in/uploads/2024/05/iv-Citizen-Charter-MoEFCC.pdf', 'guideline', 'MoEFCC Citizen Charter', 'PARIVESH service boundary', now(), false),
      (version_id, 'https://parivesh.nic.in/', 'agency', 'PARIVESH environmental clearance portal', 'Official application portal', now(), false),
      (version_id, 'https://cpcb.nic.in/rules-7/', 'agency', 'CPCB rules and EPR resources', 'Current EPR resource index', now(), false),
      (version_id, 'https://cpcb.nic.in/uploads/plasticwaste/SOP_PWM_24062024.pdf', 'guideline', 'CPCB plastic EPR SOP', 'Plastic EPR registration', now(), false),
      (version_id, 'https://cpcb.nic.in/uploads/Projects/E-Waste/FAQ_ewaste_23012024.pdf', 'faq', 'CPCB e-waste EPR FAQ', 'E-waste registration and targets', now(), false)
    on conflict do nothing;
    insert into public.opportunity_benefits (opportunity_version_id, benefit_type, label, amount_min, amount_max, percentage, conditions)
    select version_id, item->>'benefit_type', item->>'benefit_label', (item->>'amount_min')::numeric, (item->>'amount_max')::numeric, (item->>'percentage')::numeric, item->'benefit_conditions'
    where not exists (select 1 from public.opportunity_benefits where opportunity_version_id = version_id and label = item->>'benefit_label');
    insert into public.opportunity_requirements (opportunity_version_id, requirement_type, name, description, required)
    select version_id, 'document', item->>'requirement', item->>'requirement_description', true
    where not exists (select 1 from public.opportunity_requirements where opportunity_version_id = version_id and name = item->>'requirement');
    insert into public.eligibility_rule_sets (opportunity_version_id, rules, source_evidence, reviewed)
    select version_id, item->'rules', jsonb_build_array(jsonb_build_object('source_url', item->>'source_url', 'anchor', item->>'source_anchor')), false
    where not exists (select 1 from public.eligibility_rule_sets where opportunity_version_id = version_id);
    insert into public.opportunity_steps (opportunity_version_id, step_number, title, description, official_url)
    select version_id, row_number() over ()::integer, step->>'title', step->>'description', step->>'url'
    from jsonb_array_elements(item->'steps') as steps(step)
    where not exists (select 1 from public.opportunity_steps where opportunity_version_id = version_id);
    insert into public.opportunity_windows (opportunity_version_id, window_type, closes_at, label, source_evidence)
    select version_id, item->>'window_type', (item->>'window_close_at')::timestamptz, item->>'window_label', item->'window_evidence'
    where not exists (select 1 from public.opportunity_windows where opportunity_version_id = version_id);
    insert into public.review_tasks (opportunity_version_id, task_type, status)
    select version_id, 'publish', 'open'
    where not exists (select 1 from public.review_tasks where opportunity_version_id = version_id and task_type = 'publish' and status in ('open', 'in_review'));
  end loop;
end $$;
